const upsertProjectBinding = `-- name: UpsertProjectBinding :one
INSERT INTO project_bindings (
    id,
    workspace_id,
    parent_project_id,
    child_project_id,
    scope_subpath,
    created_by_actor_id
) VALUES (
    ?1,
    ?2,
    ?3,
    ?4,
    ?5,
    ?6
)
ON CONFLICT (workspace_id, parent_project_id, child_project_id) DO UPDATE SET
    scope_subpath = excluded.scope_subpath,
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
RETURNING id, workspace_id, parent_project_id, child_project_id, scope_subpath, created_by_actor_id, created_at, updated_at
`

type UpsertProjectBindingParams struct {
	ID               string  `json:"id"`
	WorkspaceID      string  `json:"workspace_id"`
	ParentProjectID  string  `json:"parent_project_id"`
	ChildProjectID   string  `json:"child_project_id"`
	ScopeSubpath     string  `json:"scope_subpath"`
	CreatedByActorID *string `json:"created_by_actor_id"`
}

// UpsertProjectBinding creates or updates a parent->child sub-project binding edge within a workspace.
func (q *Queries) UpsertProjectBinding(ctx context.Context, arg UpsertProjectBindingParams) (ProjectBinding, error) {
	row := q.db.QueryRowContext(ctx, upsertProjectBinding,
		arg.ID,
		arg.WorkspaceID,
		arg.ParentProjectID,
		arg.ChildProjectID,
		arg.ScopeSubpath,
		arg.CreatedByActorID,
	)
	var i ProjectBinding
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.ParentProjectID,
		&i.ChildProjectID,
		&i.ScopeSubpath,
		&i.CreatedByActorID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
